input.value:
timeseries active = avg(resilience4j.circuitbreaker.state), by:{name, state}, filter:in(name, array("core-banking-ledger", "fraud-scoring", "swift-gateway", "notification-service", "customer-profile", "sanctions-screening", "fx-rates"))
| fieldsAdd pct = round(arrayAvg(active) * 100, decimals:1)
| summarize {
    closed = sum(if(state == "closed", pct)),
    half_open = sum(if(state == "half_open", pct)),
    open = sum(if(state == "open", pct))
  }, by:{name}
| sort open desc
